insert into uat_steps (id, seq, area, title, instructions, expect, closes, expect_fail, fields, active, updated_at) values
  ('P1', 1, 'Business Central setup', 'No till has a shift left open from an earlier day', 'On each tester''s till, look at the open shift. If one is open from an earlier day, the till refuses to sell. Cut its Z: F11 → 6 with an empty basket. If F11 is greyed out, raise Max Drawer Hours on the functionality profile in BC, sync the till, cut the Z, then set it back to 16.', 'Every till starts the UAT with no shift, or a shift opened today.', 'VPOS-63', 'G5 (VPOS-94): a stale drawer cannot reach End of day', '[{"key":"terminal","label":"Terminal no."},{"key":"shift_found","label":"Shift found open (no. and date)"},{"key":"action","label":"What you did"}]'::jsonb, true, now()),
  ('P2', 2, 'Business Central setup', 'Price basis for two shelf-priced items', 'Pick two items with a price you can see on the shelf. In BC, open each item and note its Unit Price and whether prices include VAT.', 'You know, for each item, what the customer should pay. T4 then checks the till charges exactly that.', 'U1 (VPOS-112)', null, '[{"key":"item1","label":"Item 1 no."},{"key":"item1_shelf","label":"Item 1 shelf price"},{"key":"item1_bc","label":"Item 1 BC Unit Price"},{"key":"item2","label":"Item 2 no."},{"key":"item2_shelf","label":"Item 2 shelf price"},{"key":"item2_bc","label":"Item 2 BC Unit Price"},{"key":"incl_vat","label":"Prices include VAT? (as set in BC)"}]'::jsonb, true, now()),
  ('P3', 3, 'Business Central setup', 'Is the ZWG statement fix in this build?', 'Check VPOS-90 (G1) on VTracker and the build installed on the tills.', 'Recorded, so B4 and B5 can be read correctly. Until G1 is fixed, a statement holding a ZWG-notes sale will not balance.', 'VPOS-90', null, '[{"key":"build","label":"Build / version on the tills"},{"key":"g1_fixed","label":"G1 fixed in this build? (yes/no)"}]'::jsonb, true, now()),
  ('P4', 4, 'Business Central setup', 'Overtender allowed on both cash tenders', 'Vantage Tender Types → CASH_USD and CASH_ZWG → Overtender Allowed.', 'On for both. Without it no cashier can give change.', null, null, '[{"key":"usd_found","label":"CASH_USD value found"},{"key":"usd_after","label":"CASH_USD value after"},{"key":"zwg_found","label":"CASH_ZWG value found"},{"key":"zwg_after","label":"CASH_ZWG value after"}]'::jsonb, true, now()),
  ('P5', 5, 'Business Central setup', 'Is the USD drawer fix in this build?', 'Check VPOS-92 (G3) and VPOS-93 (G4) on VTracker against the build installed on the tills.', 'Recorded, so T1 and T26 can be read correctly. Until fixed, the till asks for a ZWG float only and never counts the USD drawer at close.', 'VPOS-92, VPOS-93', null, '[{"key":"g3_fixed","label":"G3 fixed? (yes/no)"},{"key":"g4_fixed","label":"G4 fixed? (yes/no)"}]'::jsonb, true, now()),
  ('P6', 6, 'Business Central setup', 'Staff for every tester, and a manager on each till', 'Staff list for store 5001. Each tester needs their own staff record and PIN. Each till needs at least one cashier and one manager (Manager Privileges) for the supervisor steps.', 'Distinct PINs. BC refuses two people in one store sharing a PIN.', 'VPOS-65', null, '[{"key":"cashiers","label":"Cashier staff ids"},{"key":"managers","label":"Manager staff ids"}]'::jsonb, true, now()),
  ('P7', 7, 'Business Central setup', 'Vantage Tax Mappings for LOCAL', 'Vantage Tax Mappings, VAT Bus. Posting Group LOCAL. For each product group note the ZIMRA tax id, tax code letter and percent. (ZimChoice''s store group is LOCAL, not DOMESTIC.)', 'STD155 = 517, 15.5%. The letter E makes the till declare a band as exempt (no percent). T6 shows what the slip actually declares.', 'G7 (VPOS-96)', null, '[{"key":"std155","label":"STD155: id / letter / %"},{"key":"zero","label":"ZERO: id / letter / %"},{"key":"notax","label":"NO TAX: id / letter / %"},{"key":"exempt","label":"EXEMPT: id / letter / % (or none)"}]'::jsonb, true, now()),
  ('P8', 8, 'Business Central setup', 'Every till is commissioned to store 5001', 'Start each till from the installed app, not from the repo folder, and read the store and terminal on its header.', 'Store 5001 and that till''s own terminal number. The repo''s lane.properties would make it 1001 / 100101.', 'G21 (VPOS-110)', null, '[{"key":"tills","label":"Terminals and the store each shows"}]'::jsonb, true, now()),
  ('P9', 9, 'Business Central setup', 'The drawer opens on a cash sale', 'Hardware profile used by the tills → Open Drawer on Sale.', 'On. Off, the drawer never opens on a sale.', null, null, '[{"key":"found","label":"Value found"},{"key":"after","label":"Value after"}]'::jsonb, true, now()),
  ('P10', 10, 'Business Central setup', 'Smallest note and coin', 'Currency ZWG → Vantage POS → Lowest Denomination. Vantage Tender Type CASH_USD → Rounding To.', 'ZWG 0.10. CASH_USD 0.05 only if the store gives coin change; otherwise leave 0.01 and mark T13''s rounding figure as 0.', 'VPOS-81', null, '[{"key":"zwg_found","label":"ZWG found"},{"key":"zwg_after","label":"ZWG after"},{"key":"usd_rounding","label":"CASH_USD Rounding To"}]'::jsonb, true, now()),
  ('P11', 11, 'Business Central setup', 'Cash movement reasons with a G/L account', 'Vantage cash movement reasons: at least two payout reasons, each with a G/L account.', 'The till only offers reasons that have an account. With none, every payout is refused.', 'VPOS-33', null, '[{"key":"reasons","label":"Reason codes and their G/L accounts"}]'::jsonb, true, now()),
  ('P12', 12, 'Business Central setup', 'Fiscal device, fiscal day, TIN and VAT number', 'Confirm each till has an FDMS device and that its fiscal day is open (the till never opens one). Store 5001: TIN and VAT Registration No.', 'Device and open day per till. TIN and VAT no. filled, so they print on the slip.', 'VPOS-31, G20 (VPOS-109)', null, '[{"key":"devices","label":"Device id per till"},{"key":"day","label":"Fiscal day no. open"},{"key":"tin","label":"TIN set? (yes/no)"},{"key":"vatno","label":"VAT no. set? (yes/no)"}]'::jsonb, true, now()),
  ('P13', 13, 'Business Central setup', 'Statement numbers have room', 'Vantage POS Posting Setup → Statement Nos. → No. Series lines.', 'A line covering today, with room between Last No. Used and Ending No.', null, null, '[{"key":"series","label":"Series code"},{"key":"last","label":"Last No. Used"},{"key":"ending","label":"Ending No."}]'::jsonb, true, now()),
  ('P14', 14, 'Business Central setup', 'Card terminal reachable', 'Check PayBridge is running for each till with a card terminal, and where the till is pointed at it.', 'Reachable. The hardware profile''s EFT endpoint was blank on 24 Sep.', null, null, '[{"key":"tills","label":"Tills with a card terminal"},{"key":"endpoint","label":"Endpoint set? (yes/no)"}]'::jsonb, true, now()),
  ('P15', 15, 'Business Central setup', 'A ZWG rate dated today', 'Currency Exchange Rates for ZWG.', 'A rate starting today, synced to the tills.', 'VPOS-71', null, '[{"key":"date","label":"Starting date"},{"key":"rate","label":"Rate (ZWG per USD)"}]'::jsonb, true, now()),
  ('P16', 16, 'Business Central setup', 'Posting accounts and limits', 'Vantage POS Posting Setup: Rounding Account, Cash Difference Acc., Max. Rounding Amount, Max. Cash Difference. Inventory Setup: Prevent Negative Inventory. If live stock is on, the job queue entry for codeunit 50802.', 'Accounts set. Max. Rounding Amount small, so a wrong tender cannot hide in the Rounding Account.', null, null, '[{"key":"rounding_acc","label":"Rounding Account"},{"key":"cashdiff_acc","label":"Cash Difference Acc."},{"key":"max_rounding","label":"Max. Rounding Amount"},{"key":"max_cashdiff","label":"Max. Cash Difference"},{"key":"neg_inv","label":"Prevent Negative Inventory"},{"key":"jobq","label":"Live-stock job queue entry (yes/no/n.a.)"}]'::jsonb, true, now()),
  ('T1', 17, 'Till', 'Sign on and count the float', 'Sign in as a cashier and count the float for each cash currency the till asks for.', 'The till asks for USD and ZWG, and opens a shift.', 'VPOS-33', 'G4 (VPOS-93): asks for ZWG only', '[{"key":"shift","label":"Shift no."},{"key":"asked","label":"Currencies asked for"},{"key":"usd_float","label":"USD float"},{"key":"zwg_float","label":"ZWG float"}]'::jsonb, true, now()),
  ('T2', 18, 'Till', 'Reopen without a Z', 'Close the app and reopen it without cutting a Z.', 'The same shift resumes with the float you counted, not a fresh prompt.', 'VPOS-33', null, '[{"key":"shift","label":"Shift no. after reopening"},{"key":"float","label":"Float shown"}]'::jsonb, true, now()),
  ('T3', 19, 'Till', 'A manager''s own PIN at a supervisor gate', 'As the cashier, trigger a supervisor gate (a line discount over 10%, or End of day). Enter the manager''s PIN.', 'Accepted, and the approval names the manager.', 'VPOS-65', null, '[{"key":"gate","label":"Gate used"},{"key":"approver","label":"Approver shown"}]'::jsonb, true, now()),
  ('T4', 20, 'Till', 'Till price matches the shelf', 'Scan the two items from P2.', 'The till charges exactly the shelf price.', 'U1 (VPOS-112)', null, '[{"key":"item1_till","label":"Item 1 till price (incl. VAT)"},{"key":"item1_vat","label":"Item 1 VAT"},{"key":"item2_till","label":"Item 2 till price (incl. VAT)"},{"key":"item2_vat","label":"Item 2 VAT"}]'::jsonb, true, now()),
  ('T5', 21, 'Till', 'Key an item number; find one by name', 'Key an item number with no barcode. Then press F3 and find an item by part of its name.', 'Both ring.', null, null, '[{"key":"keyed","label":"Item keyed"},{"key":"searched","label":"Item found with F3"}]'::jsonb, true, now()),
  ('T6', 22, 'Till', 'VAT and band per kind of item', 'Ring one standard-rated, one zero-rated, one exempt and one blank-VAT-group item. Look each up in BC''s VAT Posting Setup. After tendering, read the bands on the fiscal slip.', 'Each line''s VAT % equals BC''s setup for that item, and the slip declares the right band.', 'G7 (VPOS-96)', null, '[{"key":"std","label":"Standard: item, BC %, till %, band on slip"},{"key":"zero","label":"Zero-rated: item, BC %, till %, band"},{"key":"exempt","label":"Exempt: item, BC %, till %, band"},{"key":"blank","label":"Blank group: item, BC %, till %, band"}]'::jsonb, true, now()),
  ('T7', 23, 'Till', 'A zero-priced item', 'Ring an item whose price in BC is 0.', 'The till asks for a price or refuses it.', null, 'G11 (VPOS-100): rings at 0.00', '[{"key":"item","label":"Item no."},{"key":"what","label":"What happened"}]'::jsonb, true, now()),
  ('T8', 24, 'Till', 'Void a line, then a whole sale', 'Void one line of a sale and finish it. Then ring another sale and void it whole (F11 → 5).', 'Both voids are recorded and reach BC (check in B1).', null, 'G8 (VPOS-97): a voided sale leaves no record', '[{"key":"line_void_receipt","label":"Receipt with the voided line"},{"key":"void_receipt","label":"Receipt no. of the voided sale"}]'::jsonb, true, now()),
  ('T9', 25, 'Till', 'Park and recall', 'Park a basket (F8), ring and finish another sale, then recall the parked one and finish it.', 'The parked basket comes back whole.', null, null, '[{"key":"parked","label":"Parked receipt no."},{"key":"recalled_total","label":"Total after recall"}]'::jsonb, true, now()),
  ('T10', 26, 'Till', 'Sign out mid-basket', 'A manager rings two items and signs out without finishing. A cashier signs in.', 'The cashier gets a fresh basket under their own name, without the manager''s rights.', null, 'G10 (VPOS-99): keeps the basket and the previous person''s rights', '[{"key":"staff_on_receipt","label":"Staff on the next receipt"},{"key":"basket","label":"What the cashier saw"}]'::jsonb, true, now()),
  ('T11', 27, 'Till', 'Line discount at 10%, then 15%', 'As a cashier, give 10% on a line, then 15% on another.', '10% is taken; 15% asks for a supervisor.', null, null, '[{"key":"ten","label":"Line amount after 10%"},{"key":"fifteen","label":"What 15% did"}]'::jsonb, true, now()),
  ('T12', 28, 'Till', 'USD cash, exact', 'Ring a sale and tender exact USD cash.', 'The sale closes and the drawer opens.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"gross","label":"Gross"},{"key":"drawer","label":"Drawer opened? (yes/no)"}]'::jsonb, true, now()),
  ('T13', 29, 'Till', 'USD cash with change', 'Ring a sale and hand over more than the total in USD.', 'Change is shown and paid = gross + rounding + change.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"gross","label":"Gross"},{"key":"paid","label":"Paid"},{"key":"rounding","label":"Rounding"},{"key":"change","label":"Change"}]'::jsonb, true, now()),
  ('T14', 30, 'Till', 'Settle a USD sale in ZWG notes', 'Open tendering on a USD sale. Before pressing, read the Cash ZWG key. Then settle it entirely in ZWG.', 'The key shows the rate and the ZWG balance. The sale closes and the receipt names the tender by its description.', 'VPOS-79, VPOS-80, VPOS-82, VPOS-83', null, '[{"key":"receipt","label":"Receipt no."},{"key":"rate","label":"Rate on the key"},{"key":"usd","label":"USD gross"},{"key":"zwg","label":"ZWG paid"},{"key":"tender_name","label":"Tender name on the receipt"}]'::jsonb, true, now()),
  ('T15', 31, 'Till', 'An unpayable ZWG amount', 'Key a ZWG amount that is not a multiple of 0.10.', 'Refused, naming the denomination.', 'VPOS-81', null, '[{"key":"keyed","label":"Amount keyed"},{"key":"message","label":"Message shown"}]'::jsonb, true, now()),
  ('T16', 32, 'Till', 'Change from the ZWG drawer', 'Overtender a sale in ZWG notes.', 'Change comes back in ZWG, rounded to 0.10, and paid = gross + rounding + change.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"zwg_paid","label":"ZWG paid"},{"key":"change","label":"Change"},{"key":"rounding","label":"Rounding"}]'::jsonb, true, now()),
  ('T17', 33, 'Till', 'Split USD cash and ZWG notes', 'Settle one sale partly in USD cash and partly in ZWG notes.', 'The sale closes. The fiscal receipt is in the sale''s currency.', null, 'G13 (VPOS-102): fiscalises in ZWG', '[{"key":"receipt","label":"Receipt no."},{"key":"usd_leg","label":"USD leg"},{"key":"zwg_leg","label":"ZWG leg"},{"key":"fiscal_currency","label":"Currency on the fiscal receipt"}]'::jsonb, true, now()),
  ('T18', 34, 'Till', 'Card for an odd total', 'Ring a basket whose total is not a coin multiple and pay by card.', 'The card is charged the exact gross.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"gross","label":"Gross"},{"key":"charged","label":"Amount on the card slip"}]'::jsonb, true, now()),
  ('T19', 35, 'Till', 'A card decline', 'Force a decline (wrong PIN).', 'The till offers another tender and takes nothing. Do not retry a decline.', null, null, '[{"key":"response","label":"What the till showed"}]'::jsonb, true, now()),
  ('T20', 36, 'Till', 'EcoCash through the terminal', 'Take an EcoCash payment through the card terminal.', 'Declared to ZIMRA as MobileWallet, not Card (read the fiscal record or ask Wyne to).', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"money_type","label":"Money type declared"}]'::jsonb, true, now()),
  ('T21', 37, 'Till', 'A customer on account', 'F2, attach an account customer, tender on account inside the limit. Then try an amount over the limit.', 'Accepted inside the limit; refused over it with the reason.', 'VPOS-27, VPOS-56', null, '[{"key":"customer","label":"Customer no."},{"key":"receipt","label":"Receipt no."},{"key":"amount","label":"Amount"},{"key":"refusal","label":"Refusal text over the limit"}]'::jsonb, true, now()),
  ('T22', 38, 'Till', 'The fiscal slip, online and offline', 'Read a printed slip and scan its QR with a phone. Then pull the network, make one sale, and plug it back in.', 'Fiscal block, QR that verifies, VAT by band. Offline, the slip says fiscalisation is pending and the stamps arrive once the network is back.', 'VPOS-31', null, '[{"key":"day","label":"Fiscal day"},{"key":"global","label":"Global no."},{"key":"code","label":"Verification code"},{"key":"qr","label":"QR verified? (yes/no)"},{"key":"offline_receipt","label":"Offline receipt no."},{"key":"offline_stamped","label":"Stamped after reconnecting? (yes/no)"}]'::jsonb, true, now()),
  ('T23', 39, 'Till', 'Returns', 'Refund a whole receipt. Return 2 of 6 on a line, then the rest. Return a receipt from another till. Try to refund a sale that has not been fiscalised yet.', 'Credit notes of 20 characters or fewer, summing to the original to the cent. The last one is refused.', 'VPOS-57, VPOS-39', 'G12 (VPOS-101): an unfiscalised sale is not refused', '[{"key":"whole","label":"Whole return: CN no., amount"},{"key":"partials","label":"Partials: CN nos., amounts"},{"key":"other_till","label":"Other till: CN no."},{"key":"unfiscalised","label":"Unfiscalised refund: what happened"}]'::jsonb, true, now()),
  ('T24', 40, 'Till', 'Pickup, safe drop, float add, payout', 'Manager menu → 7 with an empty basket. Do one of each, including a payout with reason Other.', 'A slip each, and the drawer''s expected cash moves by exactly that amount.', 'VPOS-33, VPOS-73', null, '[{"key":"pickup","label":"Pickup amount"},{"key":"drop","label":"Safe drop amount"},{"key":"float_add","label":"Float add amount"},{"key":"payout","label":"Payout amount and reason"}]'::jsonb, true, now()),
  ('T25', 41, 'Till', 'A basket across a Z', 'Open a basket on one till. Cut the Z, open a new shift, then tender the basket.', 'The sale lands on the shift it was tendered on.', 'VPOS-64', null, '[{"key":"receipt","label":"Receipt no."},{"key":"shift","label":"Shift it landed on"}]'::jsonb, true, now()),
  ('T26', 42, 'Till', 'Declare and cut the Z', 'End of day: count each cash drawer and declare, then cut the Z. Compare the screen with the paper.', 'A USD and a ZWG drawer, each with expected, counted and variance. Screen and paper agree.', 'VPOS-35, VPOS-68', 'G3 (VPOS-92): the USD drawer is not counted', '[{"key":"z","label":"Z / shift no."},{"key":"usd","label":"USD: expected / counted / variance"},{"key":"zwg","label":"ZWG: expected / counted / variance"},{"key":"gross","label":"Z gross"},{"key":"vat","label":"VAT by band"}]'::jsonb, true, now()),
  ('B1', 43, 'Business Central', 'Every transaction arrived', 'Count the transaction headers in BC for the shifts tested and compare with the till.', 'One per sale, none missing, voids present.', 'VPOS-31', null, '[{"key":"till_count","label":"Count on the till"},{"key":"bc_count","label":"Count in BC"},{"key":"missing","label":"Missing receipt nos."}]'::jsonb, true, now()),
  ('B2', 44, 'Business Central', 'Fiscal stamps on every header', 'Check the fiscal fields on each transaction header.', 'All present.', 'VPOS-31', null, '[{"key":"missing","label":"Headers without stamps"}]'::jsonb, true, now()),
  ('B3', 45, 'Business Central', 'Cash movements and the Z report arrived', 'Vantage Cash Movements and Vantage Z Reports for the shifts tested.', 'One Z per shift, with a ladder line per currency.', 'VPOS-33, VPOS-35', null, '[{"key":"z","label":"Z report no."},{"key":"currencies","label":"Currencies on the ladder"},{"key":"movements","label":"Cash movements found"}]'::jsonb, true, now()),
  ('B4', 46, 'Business Central', 'Calculate the statement', 'Create and calculate a statement for the store and date.', 'Each tender line in its own currency at the amount taken.', null, 'G1 (VPOS-90): a ZWG-notes tender reads the USD amount as ZWG', '[{"key":"statement","label":"Statement no."},{"key":"zwg_line","label":"ZWG tender line amount"}]'::jsonb, true, now()),
  ('B5', 47, 'Business Central', 'Post the statement', 'Post it.', 'It balances.', 'VPOS-35', null, '[{"key":"revenue","label":"Revenue"},{"key":"vat","label":"Output VAT"},{"key":"tenders","label":"Tenders"},{"key":"cash_diff","label":"Cash difference"}]'::jsonb, true, now()),
  ('B6', 48, 'Business Central', 'Drawer difference per currency', 'Vantage Statement Drawer for the statement.', 'One difference per drawer and currency, matching the Z.', 'VPOS-33', null, '[{"key":"usd","label":"USD difference"},{"key":"zwg","label":"ZWG difference"}]'::jsonb, true, now()),
  ('B7', 49, 'Business Central', 'Item ledger', 'Item Ledger Entries for the day''s sales.', 'Sale quantities posted.', 'VPOS-32', null, '[{"key":"entries","label":"Entries found"}]'::jsonb, true, now()),
  ('B8', 50, 'Business Central', 'Account sale invoice and oldest-first payment', 'Find the invoice for T21''s account sale. Pay part of the customer''s balance and check what it applied to.', 'The sale is its own invoice; the payment applies to the oldest entry first.', 'VPOS-56, VPOS-40', null, '[{"key":"invoice","label":"Invoice no."},{"key":"applied","label":"Entry the payment applied to"}]'::jsonb, true, now()),
  ('B9', 51, 'Business Central', 'Post the same day again', 'Try to post the day again.', 'Nothing moves.', null, null, '[{"key":"before","label":"G/L entries before"},{"key":"after","label":"G/L entries after"}]'::jsonb, true, now()),
  ('B10', 52, 'Business Central', 'Roll the statement back', 'Roll back the posted statement.', 'A net-zero reversal, and the transactions back to Open.', null, null, '[{"key":"doc","label":"Reversal document no."},{"key":"open","label":"Transactions back to Open? (yes/no)"}]'::jsonb, true, now())
